31	/**
32	 * Converts a Brazilian date (DD/MM/YYYY) to ISO format (YYYY-MM-DD).
33	 * Also handles dates the AI may have already converted to YYYY-MM-DD (validates & fixes swaps).
34	 * Returns null if the date cannot be parsed.
35	 */
36	function convertBrazilianDateToISO(dateStr: string | null | undefined): string | null {
37	  if (!dateStr || dateStr === 'null') return null;
38	  const cleaned = dateStr.trim();
39	
40	  // Case 1: DD/MM/YYYY or DD-MM-YYYY (Brazilian format — most reliable)
41	  const brMatch = cleaned.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{4})$/);
42	  if (brMatch) {
43	    const day = brMatch[1].padStart(2, '0');
44	    const month = brMatch[2].padStart(2, '0');
45	    const year = brMatch[3];
46	    const m = parseInt(month);
47	    const d = parseInt(day);
48	    if (m >= 1 && m <= 12 && d >= 1 && d <= 31) {
49	      return `${year}-${month}-${day}`;
50	    }
51	    if (m > 12 && d >= 1 && d <= 12) {
52	      return `${year}-${day.padStart(2, '0')}-${month}`;
53	    }
54	    return `${year}-${month}-${day}`;
55	  }
56	
57	  // Case 2: YYYY-MM-DD (AI already converted — validate and fix if swapped)
58	  const isoMatch = cleaned.match(/^(\d{4})-(\d{2})-(\d{2})$/);
59	  if (isoMatch) {
60	    const year = isoMatch[1];
61	    const part1 = isoMatch[2];
62	    const part2 = isoMatch[3];
63	    const p1 = parseInt(part1);
64	    const p2 = parseInt(part2);
65	    if (p1 > 12 && p2 >= 1 && p2 <= 12) {
66	      console.log(`[DATE FIX] Swapped date detected: ${cleaned} → ${year}-${part2}-${part1}`);
67	      return `${year}-${part2}-${part1}`;
68	    }
69	    return cleaned;
70	  }
71	
72	  console.warn(`[DATE WARN] Could not parse date: ${dateStr}`);
73	  return cleaned;
74	}
