13	/**
14	 * Converte Markdown (gerado pelo LLM) para HTML aceito pelo Telegram.
15	 * Suporta: headers, bold, italic, inline code, code blocks, blockquotes, tabelas, links.
16	 */
17	export function markdownToTelegramHTML(md: string): string {
18	  let html = md;
19	  // Headers → negrito
20	  html = html.replace(/^### (.+)$/gm, '<b>$1</b>');
21	  html = html.replace(/^## (.+)$/gm, '<b>$1</b>');
22	  html = html.replace(/^# (.+)$/gm, '<b>$1</b>');
23	  // Bold
24	  html = html.replace(/\*\*(.+?)\*\*/g, '<b>$1</b>');
25	  // Italic
26	  html = html.replace(/\*(.+?)\*/g, '<i>$1</i>');
27	  // Inline code
28	  html = html.replace(/`([^`]+)`/g, '<code>$1</code>');
29	  // Blocos de código
30	  html = html.replace(/```[\s\S]*?```/g, (match) => {
31	    const content = match.replace(/```\w*\n?/g, '').replace(/```/g, '');
32	    return `<pre>${content}</pre>`;
33	  });
34	  // Blockquotes
35	  html = html.replace(/^> (.+)$/gm, '▸ <i>$1</i>');
36	  // Tabelas Markdown → bloco monospace
37	  const tableRegex = /[|](.+)[|]\n[|][-| ]+[|]\n(?:[|].+[|]\n?)+/g;
38	  html = html.replace(tableRegex, (match) => {
39	    const lines = match.trim().split('\n').filter(l => !l.match(/^[| -]+$/));
40	    const formatted = lines
41	      .map(l => l.replace(/^\||\|$/g, '').split('|').map(c => c.trim().padEnd(15)).join(''))
42	      .join('\n');
43	    return `<pre>${formatted}</pre>`;
44	  });
45	  // Links
46	  html = html.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2">$1</a>');
47	  // Limpar múltiplas quebras de linha
48	  html = html.replace(/\n{3,}/g, '\n\n');
49	  return html.trim();
50	}
