85	export function useMiaTelegram() {
86	  /**
87	   * Envia mensagem Telegram via edge function MIA.
88	   * Cria span mia.telegram.send com message_type e html_length.
89	   * Lança MiaTelegramError com código INFRA_TELEGRAM_SEND em caso de falha.
90	   */
91	  const sendTelegramMessage = async (
92	    chatId: number,
93	    text: string,
94	    replyMarkup?: Record<string, unknown>
95	  ): Promise<TelegramSendResult> => {
96	    const messageType = replyMarkup?.inline_keyboard ? 'inline_keyboard' : 'text';
97	    const htmlLength = text.length;
98	
99	    if (isInitialized() && getTelemetryConfig().enabled) {
100	      const { trace: otelTrace } = await import('@opentelemetry/api');
101	      const cfg = getTelemetryConfig();
102	      const tracer = otelTrace.getTracer(cfg.serviceName, cfg.serviceVersion);
103	
104	      return tracer.startActiveSpan(
105	        'mia.telegram.send',
106	        {
107	          attributes: {
108	            'telegram.message_type': messageType,
109	            'telegram.html_length': htmlLength,
110	          },
111	        },
112	        async (sendSpan) => {
113	          try {
114	            const result = await _invokeSendMessage(chatId, text, replyMarkup);
115	            sendSpan.setStatus({ code: 1 });
116	            sendSpan.end();
117	            return result;
118	          } catch (err) {
119	            const errCode =
120	              err instanceof MiaTelegramError
121	                ? err.code
122	                : MIA_ERROR_CODES.INFRA_TELEGRAM_SEND;
123	            sendSpan.setStatus({ code: 2, message: errCode });
124	            sendSpan.recordException(err instanceof Error ? err : new Error(String(err)));
125	            sendSpan.end();
126	            throw err;
127	          }
128	        },
