242	async function _invokeSendMessage(
243	  chatId: number,
244	  text: string,
245	  replyMarkup?: Record<string, unknown>
246	): Promise<TelegramSendResult> {
247	  try {
248	    const result = await supabase.functions.invoke('mia', {
249	      body: {
250	        _telegram_send: true,
251	        chat_id: chatId,
252	        text,
253	        reply_markup: replyMarkup,
254	      },
255	    });
256	
257	    if (result.error) {
258	      throw new MiaTelegramError({
259	        code: MIA_ERROR_CODES.INFRA_TELEGRAM_SEND,
260	        message: `Falha ao enviar mensagem Telegram: ${result.error.message}`,
261	        cause: result.error,
262	      });
263	    }
264	
265	    return { messageId: result.data?.message_id || null, success: true };
266	  } catch (err) {
267	    if (err instanceof MiaTelegramError) throw err;
268	    throw new MiaTelegramError({
269	      code: MIA_ERROR_CODES.INFRA_TELEGRAM_SEND,
270	      message: 'Erro inesperado ao enviar mensagem Telegram',
271	      cause: err instanceof Error ? err : new Error(String(err)),
272	    });
273	  }
274	}
