310	async function _handleCallbackQueryImpl(
311	  handler: TelegramCallbackHandler
312	): Promise<{ authenticated: boolean; userId?: string }> {
313	  try {
314	    // Verifica se o usuário tem perfil Telegram vinculado
315	    const { data: profile, error } = await supabase
316	      .from('profiles')
317	      .select('id, telegram_id')
318	      .eq('telegram_id', handler.callbackQueryId)
319	      .maybeSingle();
320	
321	    if (error) {
322	      throw new MiaTelegramError({
323	        code: MIA_ERROR_CODES.INFRA_TELEGRAM_AUTH,
324	        message: `Falha ao verificar autenticação Telegram: ${error.message}`,
325	        cause: error,
326	      });
327	    }
328	
329	    if (!profile) {
330	      return { authenticated: false };
331	    }
332	
333	    return { authenticated: true, userId: profile.id };
334	  } catch (err) {
335	    if (err instanceof MiaTelegramError) throw err;
336	    throw new MiaTelegramError({
337	      code: MIA_ERROR_CODES.INFRA_TELEGRAM_AUTH,
338	      message: 'Erro inesperado na autenticação Telegram',
339	      cause: err instanceof Error ? err : new Error(String(err)),
340	    });
341	  }
342	}
